/**
 * The committed Codex app-server protocol surface of the pinned CLI version
 * (protocol-surface.json, regenerated by
 * packages/domains/terminal/src/server/agents/codex/codex-protocol-surface.gen.ts).
 * The fake reports this version, the transcripts were recorded with it, and the
 * drift check compares the driver against it.
 *
 * @module test-utils/fake-codex/protocol
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const CODEX_PROTOCOL_SURFACE_PATH = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  'protocol-surface.json'
)

export interface CodexProtocolSurface {
  cliVersion: string
  generatedBy: string
  /** method → params definition name. */
  serverNotifications: Record<string, string | null>
  /** method → params definition + the `decision` values its response accepts (`{key}` = object variant). */
  serverRequests: Record<string, { params: string | null; decisions: string[] }>
  /** method → params definition, its required keys and every key it accepts. */
  clientRequests: Record<
    string,
    { params: string | null; required: string[]; properties: string[] }
  >
  threadItemTypes: string[]
  enums: Record<string, string[]>
}

export function readCodexProtocolSurface(): CodexProtocolSurface {
  return JSON.parse(fs.readFileSync(CODEX_PROTOCOL_SURFACE_PATH, 'utf8')) as CodexProtocolSurface
}
